from fractions import Fraction
import math

def is_square_of_rational(r: Fraction) -> bool:
    """Checks if a rational number r is the square of a rational number."""
    if r < 0:
        return False

    # Get the numerator and denominator in reduced form
    numerator = r.numerator
    denominator = r.denominator

    # Check if both numerator and denominator are perfect squares of integers
    def is_perfect_square(n):
        if n < 0:
            return False
        sqrt_n = int(math.isqrt(n))
        return sqrt_n * sqrt_n == n

    return is_perfect_square(numerator) and is_perfect_square(denominator)

a_values = [0, 1, -1, Fraction(1, 2), Fraction(-1, 2), 3]
results = {}

for a in a_values:
    # Calculate a/(a-2)
    if a == 2:
        # Should not happen based on input list, but good practice
        b_squared = None
        status = "Undefined (a=2)"
    else:
        term2 = a / (a - 2)
        a_squared = a * a
        b_squared = a_squared - term2
        status = "Calculated"

    is_sq = is_square_of_rational(b_squared) if b_squared is not None else None

    results[a] = {
        "b_squared": b_squared,
        "is_rational_square": is_sq,
        "status": status
    }

for a, result in results.items():
    print(f"a = {a}:")
    print(f"  b^2 = {result['b_squared']}")
    print(f"  Is b^2 a square of a rational number? {result['is_rational_square']}")
